//! 🧺️ Original request-owned finite REAL arrays reconstruct only explicit prefix and blank-member choices.
use super::{DslValue,invalid,construct_row_string};
use semio_framework_job::{OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,StepContext,admit_original_construction};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits},retirement::{RetireOwned,RetirementCursor,RetirementStep}};
use std::mem::{ManuallyDrop,size_of};
#[derive(semio_framework_value::RetireOwned)]
struct Parts{strings:[Option<String>;5],member:Option<Vec<(String,DslValue)>>,bits:Option<Vec<(String,DslValue)>>,root:Option<Vec<DslValue>>,output:Option<DslValue>}
#[derive(Clone,Copy,PartialEq,Eq)]
pub(super) enum Mode{Real,Integer}
#[derive(Clone,Copy,Default)]
struct State{phase:u8,member:usize,string:usize,offset:usize}
pub(super) struct ListCopy{parts:ManuallyDrop<Option<Parts>>,retirement:RetainedCloneClose,state:State,binding:Option<OriginalSourceBinding>,source:Option<(usize,usize,usize,Mode)>,closing:bool}
impl Default for ListCopy{fn default()->Self{Self{parts:ManuallyDrop::new(None),retirement:Default::default(),state:Default::default(),binding:None,source:None,closing:false}}}
pub(super) fn word(source:&[DslValue],index:usize,mode:Mode)->Result<&str,ValueError>{let Some(value)=source.get(index)else{return Ok("")};match mode{Mode::Real=>super::super::type_input::real_word(value),Mode::Integer=>super::super::type_input::integer_word(value)}.ok_or_else(invalid)}
fn literal(mode:Mode,index:usize)->Result<&'static str,ValueError>{["kind",if mode==Mode::Real{"real"}else{"integer"},"value","bits"].get(index).copied().ok_or_else(invalid)}
impl ListCopy{
 fn bytes()->usize{3*size_of::<Self>()+2*size_of::<Parts>()+2*size_of::<DslValue>()}
 fn valid(&self,source:&[DslValue],target:usize,mode:Mode)->Result<(),ValueError>{target.checked_mul(size_of::<DslValue>()).ok_or_else(invalid)?;if self.source.is_some_and(|identity|identity!=(source.as_ptr()as usize,source.len(),target,mode)){return Err(invalid());}Ok(())}
 pub(super) fn demands(&self,source:&[DslValue],target:usize,mode:Mode)->Result<RetirementDemand,ValueError>{self.valid(source,target,mode)?;let mut demand=RetirementDemand{copy_bytes:Self::bytes(),depth:1,..Default::default()};match self.state.phase{1=>demand.capacity_bytes=target*size_of::<DslValue>(),2 if self.state.member<target=>demand.capacity_bytes=2*size_of::<(String,DslValue)>(),3 if mode==Mode::Real=>demand.capacity_bytes=size_of::<(String,DslValue)>(),4 if self.state.string<5&&!(mode==Mode::Integer&&self.state.string==3)=>{let text=if self.state.string==4{word(source,self.state.member,mode)?}else{literal(mode,self.state.string)?};demand.capacity_bytes=text.len();demand.copy_bytes+=size_of::<String>()+if self.state.string==4{0}else{2*text.len()};},5=>demand.copy_bytes+=192+size_of::<String>(),_=>{}}Ok(demand)}
 pub(super) fn advance(&mut self,source:&[DslValue],target:usize,mode:Mode,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.valid(source,target,mode)?;if self.closing||self.binding.is_some_and(|binding|!binding.matches(cx)){return Err(invalid().into());}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"staging LIST copy cancelled").into());}let demand=self.demands(source,target,mode)?;if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),demand){return Ok(false);}if self.state.phase==8{return Ok(true);}let base=Self::bytes();
  match self.state.phase{
   0=>{*self.parts=Some(Parts{strings:Default::default(),member:None,bits:None,root:None,output:None});self.binding=Some(OriginalSourceBinding::borrow(cx));self.source=Some((source.as_ptr()as usize,source.len(),target,mode));self.state.phase=1;},
   1=>{let physical=OriginalConstructionDemand{items:1,copy_bytes:base,capacity_bytes:target*size_of::<DslValue>(),release_bytes:0,depth:1};if admit_original_construction(cx,&mut self.parts.as_mut().ok_or_else(invalid)?.root,physical,|_|{let mut values=Vec::new();values.try_reserve_exact(target).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"LIST option members"))?;let capacity=values.capacity()*size_of::<DslValue>();Ok((values,RetainedCloneProgress{copied_items:1,copied_bytes:base,retained_capacity_bytes:capacity,..Default::default()}))})?{self.state.phase=2;}return Ok(false);},
   2 if self.state.member==target=>self.state.phase=7,
   3 if mode==Mode::Integer=>self.state.phase=4,
   2|3=>{let count=if self.state.phase==2{2}else{1};let physical=OriginalConstructionDemand{items:1,copy_bytes:base,capacity_bytes:count*size_of::<(String,DslValue)>(),release_bytes:0,depth:1};let parts=self.parts.as_mut().ok_or_else(invalid)?;let output=if self.state.phase==2{&mut parts.member}else{&mut parts.bits};if admit_original_construction(cx,output,physical,|_|{let mut fields=Vec::new();fields.try_reserve_exact(count).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"LIST option real object"))?;let capacity=fields.capacity()*size_of::<(String,DslValue)>();Ok((fields,RetainedCloneProgress{copied_items:1,copied_bytes:base,retained_capacity_bytes:capacity,..Default::default()}))})?{self.state.phase+=1;}return Ok(false);},
   4 if self.state.string==3&&mode==Mode::Integer=>self.state.string=4,
   4 if self.state.string<5=>{let raw=self.state.string==4;let text=if raw{word(source,self.state.member,mode)?}else{literal(mode,self.state.string)?};let physical=OriginalConstructionDemand{items:1,copy_bytes:demand.copy_bytes,capacity_bytes:text.len(),release_bytes:0,depth:1};if construct_row_string(&mut self.parts.as_mut().ok_or_else(invalid)?.strings[self.state.string],text.len(),if raw{""}else{text},physical,cx)?{if raw{self.state.offset=0;self.state.phase=5;}else{self.state.string+=1;}}return Ok(false);},
   4=>self.state.phase=6,
   5=>{let text=word(source,self.state.member,mode)?;let mut end=(self.state.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1;}let chunk=&text[self.state.offset..end];let mut bytes=[0u8;64];bytes[..chunk.len()].copy_from_slice(chunk.as_bytes());self.parts.as_mut().ok_or_else(invalid)?.strings[4].as_mut().ok_or_else(invalid)?.push_str(std::str::from_utf8(&bytes[..chunk.len()]).expect("UTF8 boundary"));self.state.offset=end;if end==text.len(){self.state.string=5;self.state.phase=4;}},
   6=>{let parts=self.parts.as_mut().ok_or_else(invalid)?;if parts.member.is_none()||parts.root.is_none()||[0,1,2,4].iter().any(|index|parts.strings[*index].is_none())||mode==Mode::Real&&(parts.bits.is_none()||parts.strings[3].is_none()){return Err(invalid().into());}let text=DslValue::String(parts.strings[4].take().unwrap());let value=if mode==Mode::Real{let mut bits=parts.bits.take().unwrap();bits.push((parts.strings[3].take().unwrap(),text));DslValue::Object(bits)}else{text};let mut member=parts.member.take().unwrap();member.push((parts.strings[0].take().unwrap(),DslValue::String(parts.strings[1].take().unwrap())));member.push((parts.strings[2].take().unwrap(),value));parts.root.as_mut().unwrap().push(DslValue::Object(member));self.state.member+=1;self.state.string=0;self.state.phase=2;},
   7=>{let parts=self.parts.as_mut().ok_or_else(invalid)?;parts.output=Some(DslValue::Array(parts.root.take().ok_or_else(invalid)?));self.state.phase=8;},
   _=>return Err(invalid().into()),
  }
  cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;cx.consume_fuel(1);Ok(self.state.phase==8)
 }
 pub(super) fn take(&mut self,output:&mut Option<DslValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.closing||self.state.phase!=8||output.is_some()||self.binding.is_none_or(|binding|!binding.matches(cx)){return Err(invalid().into());}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"staging LIST take cancelled").into());}let demand=RetirementDemand{copy_bytes:Self::bytes(),depth:1,..Default::default()};if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),demand){return Ok(false);}*output=self.parts.as_mut().ok_or_else(invalid)?.output.take();if output.is_none(){return Err(invalid().into());}self.state.phase=9;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
 pub(super) fn begin_close(&mut self){self.closing=true;}
 pub(super) fn empty(&self)->bool{self.parts.is_none()&&self.retirement.is_empty()}
 pub(super) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.retirement.next_owner_demands::<Parts>(self.parts.is_some(),&None,body)}
 pub(super) fn close_owned(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid());}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}if self.parts.is_some(){return self.retirement.begin_granted(&mut self.parts,grant)?.ok_or_else(invalid);}Ok(RetainedCloneStep::Complete(Default::default()))}
}
impl RetireOwned for ListCopy{fn retirement(mut self)->Box<dyn RetirementCursor>{self.begin_close();Box::new(self)}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<Self>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for ListCopy{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands(body)}fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{match self.close_owned(grant){Ok(RetainedCloneStep::Complete(progress))if progress==Default::default()&&self.empty()=>RetirementStep::Complete,Ok(step)=>RetirementStep::Progress(step.progress()),Err(error)=>RetirementStep::Failure(error)}}fn terminal_is_empty(&self)->bool{self.empty()}fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.copy_bytes)}fn next_selected_work_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.close_demands(body)?.copy_bytes)}fn allows_admitted_narrow_work(&self)->bool{!self.empty()}fn next_birth_bytes(&self,body:usize)->Option<usize>{self.close_demands(body).ok().map(|demand|demand.capacity_bytes)}fn next_close_byte_demand(&self)->Option<usize>{self.close_demands(4096).ok().map(|demand|demand.release_bytes)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.depth)}fn terminal_release_bytes(&self)->Option<usize>{self.empty().then_some(size_of::<Self>())}}
impl Drop for ListCopy{fn drop(&mut self){assert!(std::thread::panicking()||self.empty(),"LIST option requires original paid retirement");if self.empty(){unsafe{ManuallyDrop::drop(&mut self.parts);}}}}
